package com.example.leetcodetrainer.implementation.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="implementation_records", uniqueConstraints=@UniqueConstraint(columnNames="attempt_id")) public class ImplementationRecord {
 @Id private UUID id; @Column(name="attempt_id",nullable=false) private UUID attemptId; @Column(name="stage_assessment_id",nullable=false) private UUID stageAssessmentId; private String language; @Enumerated(EnumType.STRING) private ImplementationStatus implementationStatus; private boolean firstPassCompiled,firstPassPassedBasicCases,firstPassPassedEdgeCases,finalImplementationCompleted,selfDetectedError,usedHint,usedExternalSolution; private int compileErrorCount,wrongAnswerCount,runtimeErrorCount,timeoutCount; @Lob private String notes; private Instant createdAt,updatedAt;
 protected ImplementationRecord(){} public ImplementationRecord(UUID id,UUID attemptId,UUID stageId,String language,Instant now){this.id=id;this.attemptId=attemptId;this.stageAssessmentId=stageId;this.language=language;implementationStatus=ImplementationStatus.NOT_STARTED;createdAt=now;updatedAt=now;}
 public void save(ImplementationStatus status,boolean compiled,boolean basic,boolean edge,boolean completed,boolean self,boolean hint,int compile,int wrong,int runtime,int timeout,String notes,Instant now){implementationStatus=status;firstPassCompiled=compiled;firstPassPassedBasicCases=basic;firstPassPassedEdgeCases=edge;finalImplementationCompleted=completed;selfDetectedError=self;usedHint=hint;compileErrorCount=compile;wrongAnswerCount=wrong;runtimeErrorCount=runtime;timeoutCount=timeout;this.notes=notes;updatedAt=now;}
 public UUID getId(){return id;} public UUID getAttemptId(){return attemptId;} public ImplementationStatus getImplementationStatus(){return implementationStatus;} public boolean isFinalImplementationCompleted(){return finalImplementationCompleted;} public boolean isSelfDetectedError(){return selfDetectedError;} public boolean isUsedHint(){return usedHint;}
}
